{
  "findings": [
    {
      "ref": "[D522]",
      "area": "contact",
      "claim": "A parent reports that live, unmoderated voice and text chat can expose children to random strangers and profanity.",
      "stance": "risk",
      "quote": "Live, unmoderated chat is possible between users in the console and PC versions of Fortnite: Battle Royale. Options include voice chat and on-screen text chat. This exposes players to random strangers and the likelihood of profanity."
    },
    {
      "ref": "[D522]",
      "area": "contact",
      "claim": "Voice chat can be turned off through the Audio settings in the game.",
      "stance": "mitigation",
      "quote": "Open the Settings menu in the top right of the main Fortnite page by selecting the three bars, then the cog icon. Choose the Audio tab at the top of the screen. From there, you can adjust several audio features, including voice chat. Turn the setting from on to off by tapping the arrows."
    },
    {
      "ref": "[D522]",
      "area": "money",
      "claim": "The game encourages purchases of new content through seasonal Battle Passes.",
      "stance": "risk",
      "quote": "Seasons seem to update approximately every 10–12 weeks, and 10 seasons make up a chapter. You'll begin to see clues to the updates during the current season, usually to encourage players to purchase the next season's Battle Pass."
    },
    {
      "ref": "[D522]",
      "area": "data",
      "claim": "The platform collects user data and may share it with third parties for advertising, and users can delete their data.",
      "stance": "neutral",
      "quote": "The platform's live events, which are often tied to a feature in the game, can attract tens of millions of viewers (not just players) around the world."
    }
  ]
}
